import { describe, it, expect } from 'vitest';
import { formatDate } from './formatter';

describe('formatDate', () => {
  it('should format a valid date as YYYY-MM-DD', () => {
    const date = new Date('2023-12-25T10:30:00Z');
    expect(formatDate(date)).toBe('2023-12-25');
  });

  it('should handle single digit months and days with leading zeros', () => {
    const date = new Date('2023-01-05T10:30:00Z');
    expect(formatDate(date)).toBe('2023-01-05');
  });

  it('should handle leap year dates correctly', () => {
    const date = new Date('2024-02-29T10:30:00Z');
    expect(formatDate(date)).toBe('2024-02-29');
  });

  it('should handle date at year start', () => {
    const date = new Date('2023-01-01T00:00:00Z');
    expect(formatDate(date)).toBe('2023-01-01');
  });

  it('should handle date at year end', () => {
    const date = new Date('2023-12-31T23:59:59Z');
    expect(formatDate(date)).toBe('2023-12-31');
  });

  it('should handle different timezones correctly', () => {
    const date = new Date('2023-06-15T20:00:00-05:00');
    expect(formatDate(date)).toBe('2023-06-15');
  });

  it('should throw error for invalid date', () => {
    const date = new Date('invalid');
    expect(() => formatDate(date)).toThrow('Invalid date');
  });

  it('should throw error for null input', () => {
    expect(() => formatDate(null as any)).toThrow('Invalid date');
  });

  it('should throw error for undefined input', () => {
    expect(() => formatDate(undefined as any)).toThrow('Invalid date');
  });

  it('should handle minimum valid date', () => {
    const date = new Date('0001-01-01T00:00:00Z');
    expect(formatDate(date)).toBe('0001-01-01');
  });

  it('should handle maximum practical date', () => {
    const date = new Date('9999-12-31T23:59:59Z');
    expect(formatDate(date)).toBe('9999-12-31');
  });
});

